-- The schema as one baseline, with the rows a fresh install needs before a
-- seed load. Generated by pg_dump from the schema itself, not written by
-- hand; the baseline migration runs it. Later changes are new migrations.

CREATE EXTENSION IF NOT EXISTS fuzzystrmatch WITH SCHEMA public;

COMMENT ON EXTENSION fuzzystrmatch IS 'determine similarities and distance between strings';

