CREATE TABLE public.inventory_item (
    id integer NOT NULL,
    purchase_order_id integer,
    item_kind_id integer NOT NULL,
    denomination_id integer,
    bullion_form_id integer,
    set_form_id integer,
    storage_form_id integer NOT NULL,
    piece_count integer DEFAULT 1 CONSTRAINT inventory_item_storage_quantity_not_null NOT NULL,
    country_id integer,
    year_start integer,
    year_end integer,
    grade_id integer,
    grade_designation_id integer,
    grading_service_id integer,
    authenticity_id integer NOT NULL,
    status_id integer NOT NULL,
    disposition_id integer NOT NULL,
    storage_location_id integer,
    local_catalog_number character varying(64),
    source_title character varying(500) DEFAULT ''::character varying CONSTRAINT inventory_item_title_not_null NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    listing_url character varying(1000),
    rating text,
    item_cost numeric(12,2) CONSTRAINT inventory_item_price_not_null NOT NULL,
    shipping_cost numeric(12,2) CONSTRAINT inventory_item_shipping_not_null NOT NULL,
    tax_rate numeric(6,4) NOT NULL,
    sales_tax numeric(12,2) GENERATED ALWAYS AS (round(((item_cost +
CASE
    WHEN tax_includes_shipping THEN shipping_cost
    ELSE (0)::numeric
END) * tax_rate), 2)) STORED CONSTRAINT inventory_item_taxes_not_null NOT NULL,
    total_cost numeric(12,2) GENERATED ALWAYS AS (((item_cost + shipping_cost) + round(((item_cost +
CASE
    WHEN tax_includes_shipping THEN shipping_cost
    ELSE (0)::numeric
END) * tax_rate), 2))) STORED NOT NULL,
    numismatic_value numeric(12,2),
    valuation_basis_id integer NOT NULL,
    composition_id integer,
    metal_id integer,
    fineness numeric(6,4),
    gross_weight_ozt numeric(12,6),
    fine_weight_ozt numeric(12,6),
    weight_note text,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    source public.provenance_source NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    item_code character varying(32) DEFAULT ('CC-'::text || lpad((nextval('public.item_code_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    parent_item_id integer,
    split_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    series_id integer,
    deleted_at timestamp with time zone,
    tax_includes_shipping boolean NOT NULL,
    strike_type_id integer,
    CONSTRAINT ck_inventory_item_cost_non_negative CHECK ((item_cost >= (0)::numeric)),
    CONSTRAINT ck_inventory_item_fine_weight_non_negative CHECK (((fine_weight_ozt IS NULL) OR (fine_weight_ozt >= (0)::numeric))),
    CONSTRAINT ck_inventory_item_fine_within_gross CHECK (((fine_weight_ozt IS NULL) OR (gross_weight_ozt IS NULL) OR (fine_weight_ozt <= gross_weight_ozt))),
    CONSTRAINT ck_inventory_item_fineness_fraction CHECK (((fineness IS NULL) OR ((fineness > (0)::numeric) AND (fineness <= (1)::numeric)))),
    CONSTRAINT ck_inventory_item_gross_weight_non_negative CHECK (((gross_weight_ozt IS NULL) OR (gross_weight_ozt >= (0)::numeric))),
    CONSTRAINT ck_inventory_item_piece_count_positive CHECK ((piece_count > 0)),
    CONSTRAINT ck_inventory_item_shipping_non_negative CHECK ((shipping_cost >= (0)::numeric)),
    CONSTRAINT ck_inventory_item_year_range CHECK (((year_end IS NULL) OR (year_start IS NULL) OR (year_end >= year_start)))
);

