CREATE VIEW public.coin_inventory AS
 SELECT i.id,
    i.source_title,
    i.description,
    k.code AS item_kind,
    d.code AS denomination,
    d.label AS denomination_label,
    bf.code AS bullion_form,
    sf.code AS set_form,
    stf.code AS storage_form,
    i.piece_count,
    c.code AS country,
    i.year_start,
    i.year_end,
    m.mark AS mint_mark,
    m.label AS mint,
    cd.variety,
    cd.pcgs_type_id,
    cd.pcgs_status,
    stk.code AS strike_type,
    public.grade_display((stk.prefix)::text, (stk.suffix)::text, g.numeric_value, g.is_plus, (g.label)::text, ((gsc.code)::text = 'sheldon'::text)) AS grade,
    g.numeric_value AS grade_value,
    g.grade_rank,
    gd.code AS grade_designation,
    gs.code AS grading_service,
    a.code AS authenticity,
    st.code AS status,
    disp.code AS disposition,
    i.item_code,
    i.parent_item_id,
    i.split_at,
    i.storage_location_id,
    i.local_catalog_number,
    i.item_cost,
    i.shipping_cost,
    i.sales_tax,
    i.total_cost,
    i.numismatic_value,
    vb.code AS valuation_basis,
    mt.code AS metal,
    i.fineness,
    i.gross_weight_ozt,
    i.fine_weight_ozt,
    i.weight_note,
    i.attributes,
    i.created_at,
    i.updated_at
   FROM ((((((((((((((((((public.inventory_item i
     JOIN public.item_kind k ON ((k.id = i.item_kind_id)))
     JOIN public.storage_form stf ON ((stf.id = i.storage_form_id)))
     JOIN public.authenticity a ON ((a.id = i.authenticity_id)))
     JOIN public.item_status st ON ((st.id = i.status_id)))
     JOIN public.disposition disp ON ((disp.id = i.disposition_id)))
     JOIN public.valuation_basis vb ON ((vb.id = i.valuation_basis_id)))
     LEFT JOIN public.coin_detail cd ON ((cd.inventory_item_id = i.id)))
     LEFT JOIN public.denomination d ON ((d.id = i.denomination_id)))
     LEFT JOIN public.bullion_form bf ON ((bf.id = i.bullion_form_id)))
     LEFT JOIN public.set_form sf ON ((sf.id = i.set_form_id)))
     LEFT JOIN public.country c ON ((c.id = i.country_id)))
     LEFT JOIN public.mint m ON ((m.id = cd.mint_id)))
     LEFT JOIN public.grade g ON ((g.id = i.grade_id)))
     LEFT JOIN public.grade_scale gsc ON ((gsc.id = g.grade_scale_id)))
     LEFT JOIN public.strike_type stk ON ((stk.id = i.strike_type_id)))
     LEFT JOIN public.grade_designation gd ON ((gd.id = i.grade_designation_id)))
     LEFT JOIN public.grading_service gs ON ((gs.id = i.grading_service_id)))
     LEFT JOIN public.metal mt ON ((mt.id = i.metal_id)))
  WHERE ((i.split_at IS NULL) AND (i.deleted_at IS NULL) AND ((k.code)::text = ANY ((ARRAY['coin'::character varying, 'bullion'::character varying, 'set'::character varying, 'medal'::character varying, 'token'::character varying])::text[])));

CREATE TABLE public.composition (
    id integer NOT NULL,
    denomination_id integer NOT NULL,
    country_id integer NOT NULL,
    year_from integer NOT NULL,
    year_to integer,
    metal_id integer NOT NULL,
    fineness numeric(6,4) NOT NULL,
    gross_weight_ozt numeric(12,6),
    fine_weight_ozt numeric(12,6) NOT NULL,
    note character varying(500),
    source public.provenance_source NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_composition_fine_weight_non_negative CHECK ((fine_weight_ozt >= (0)::numeric)),
    CONSTRAINT ck_composition_fineness_fraction CHECK (((fineness > (0)::numeric) AND (fineness <= (1)::numeric))),
    CONSTRAINT ck_composition_year_range CHECK (((year_to IS NULL) OR (year_to >= year_from)))
);

