CREATE VIEW public.currency_inventory AS
 SELECT i.id,
    i.source_title,
    i.description,
    k.code AS item_kind,
    d.code AS denomination,
    d.label AS denomination_label,
    stf.code AS storage_form,
    i.piece_count,
    c.code AS country,
    i.year_start,
    i.year_end,
    nt.code AS note_type,
    cud.series_year,
    cud.series_letter,
    sc.code AS seal_color,
    fd.letter AS fed_district_letter,
    fd.city AS fed_district_city,
    cud.serial_number,
    cud.friedberg_id,
    fr.fr_number AS friedberg_number,
    cud.friedberg_status,
    sig.treasurer,
    sig.secretary,
    g.code AS grade,
    g.numeric_value AS grade_value,
    gd.code AS grade_designation,
    gs.code AS grading_service,
    a.code AS authenticity,
    st.code AS status,
    disp.code AS disposition,
    i.item_code,
    i.parent_item_id,
    i.split_at,
    i.storage_location_id,
    i.local_catalog_number,
    i.item_cost,
    i.shipping_cost,
    i.sales_tax,
    i.total_cost,
    i.numismatic_value,
    vb.code AS valuation_basis,
    i.attributes,
    i.created_at,
    i.updated_at
   FROM (((((((((((((((((public.inventory_item i
     JOIN public.item_kind k ON ((k.id = i.item_kind_id)))
     JOIN public.storage_form stf ON ((stf.id = i.storage_form_id)))
     JOIN public.authenticity a ON ((a.id = i.authenticity_id)))
     JOIN public.item_status st ON ((st.id = i.status_id)))
     JOIN public.disposition disp ON ((disp.id = i.disposition_id)))
     JOIN public.valuation_basis vb ON ((vb.id = i.valuation_basis_id)))
     LEFT JOIN public.currency_detail cud ON ((cud.inventory_item_id = i.id)))
     LEFT JOIN public.denomination d ON ((d.id = i.denomination_id)))
     LEFT JOIN public.country c ON ((c.id = i.country_id)))
     LEFT JOIN public.note_type nt ON ((nt.id = cud.note_type_id)))
     LEFT JOIN public.seal_color sc ON ((sc.id = cud.seal_color_id)))
     LEFT JOIN public.fed_district fd ON ((fd.id = cud.fed_district_id)))
     LEFT JOIN public.signature_combination sig ON ((sig.id = cud.signature_combination_id)))
     LEFT JOIN public.friedberg_number fr ON ((fr.id = cud.friedberg_id)))
     LEFT JOIN public.grade g ON ((g.id = i.grade_id)))
     LEFT JOIN public.grade_designation gd ON ((gd.id = i.grade_designation_id)))
     LEFT JOIN public.grading_service gs ON ((gs.id = i.grading_service_id)))
  WHERE ((i.split_at IS NULL) AND (i.deleted_at IS NULL) AND ((k.code)::text = 'currency'::text));

