    CONSTRAINT ck_metal_price_non_negative CHECK ((price_per_ozt >= (0)::numeric))
);

CREATE VIEW public.item_valuation AS
 WITH latest_spot AS (
         SELECT DISTINCT ON (metal_price.metal_id) metal_price.metal_id,
            metal_price.price_per_ozt,
            metal_price.quoted_at
           FROM public.metal_price
          ORDER BY metal_price.metal_id, metal_price.quoted_at DESC
        ), computed AS (
         SELECT i.id AS inventory_item_id,
            i.item_kind_id,
            i.total_cost,
            i.numismatic_value,
            i.piece_count,
            i.fine_weight_ozt,
            vb.code AS valuation_basis,
            s.price_per_ozt AS spot_price_used,
            s.quoted_at AS spot_quoted_at,
                CASE
                    WHEN ((i.fine_weight_ozt IS NULL) OR (s.price_per_ozt IS NULL)) THEN NULL::numeric
                    ELSE round(((i.fine_weight_ozt * s.price_per_ozt) * (i.piece_count)::numeric), 2)
                END AS melt_value
           FROM ((public.inventory_item i
             JOIN public.valuation_basis vb ON ((vb.id = i.valuation_basis_id)))
             LEFT JOIN latest_spot s ON ((s.metal_id = i.metal_id)))
          WHERE ((i.split_at IS NULL) AND (i.deleted_at IS NULL))
        )
 SELECT inventory_item_id,
    item_kind_id,
    total_cost,
    numismatic_value,
    piece_count,
    fine_weight_ozt,
    valuation_basis,
    spot_price_used,
    spot_quoted_at,
    melt_value,
        CASE valuation_basis
            WHEN 'melt'::text THEN melt_value
            WHEN 'numismatic'::text THEN numismatic_value
            WHEN 'manual'::text THEN numismatic_value
            ELSE NULL::numeric
        END AS reported_value,
    (
        CASE valuation_basis
            WHEN 'melt'::text THEN melt_value
            WHEN 'numismatic'::text THEN numismatic_value
            WHEN 'manual'::text THEN numismatic_value
            ELSE NULL::numeric
        END - total_cost) AS profit,
    ((
        CASE valuation_basis
            WHEN 'melt'::text THEN melt_value
            WHEN 'numismatic'::text THEN numismatic_value
            WHEN 'manual'::text THEN numismatic_value
            ELSE NULL::numeric
        END - total_cost) / NULLIF(total_cost, (0)::numeric)) AS profit_pct
   FROM computed c;

CREATE TABLE public.listing (
    id integer NOT NULL,
    inventory_item_id integer,
    price numeric(12,2) NOT NULL,
    currency_id integer NOT NULL,
    quantity_available integer DEFAULT 1 NOT NULL,
    title character varying(500) DEFAULT ''::character varying NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    listed_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    sales_venue_id integer NOT NULL,
    format public.listing_format NOT NULL,
    status public.listing_status NOT NULL,
    is_active boolean GENERATED ALWAYS AS ((status = 'active'::public.listing_status)) STORED NOT NULL,
    external_id character varying(128),
    external_url character varying(1000),
    paused_by_listing_id integer,
    sales_lot_id integer,
    CONSTRAINT ck_listing_item_xor_lot CHECK (((inventory_item_id IS NULL) <> (sales_lot_id IS NULL))),
    CONSTRAINT ck_listing_lot_quantity_one CHECK (((sales_lot_id IS NULL) OR (quantity_available <= 1))),
    CONSTRAINT ck_listing_price_non_negative CHECK ((price >= (0)::numeric)),
    CONSTRAINT ck_listing_quantity_non_negative CHECK ((quantity_available >= 0))
);

