    is_own_store boolean DEFAULT false NOT NULL,
    vendor_id integer,
    account_handle character varying(255),
    listing_url_template character varying(500),
    commission_rate numeric(6,4),
    processing_rate numeric(6,4),
    processing_fixed numeric(12,2),
    listing_fee numeric(12,2),
    terms_as_of date,
    notes text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_sales_venue_commission_rate CHECK (((commission_rate >= (0)::numeric) AND (commission_rate <= (1)::numeric))),
    CONSTRAINT ck_sales_venue_listing_fee CHECK ((listing_fee >= (0)::numeric)),
    CONSTRAINT ck_sales_venue_processing_fixed CHECK ((processing_fixed >= (0)::numeric)),
    CONSTRAINT ck_sales_venue_processing_rate CHECK (((processing_rate >= (0)::numeric) AND (processing_rate <= (1)::numeric)))
);

CREATE VIEW public.public_catalog AS
 SELECT l.id AS listing_id,
    l.price AS listing_price,
    cur.code AS listing_currency,
    l.quantity_available,
    l.listed_at,
    COALESCE(NULLIF((l.title)::text, ''::text), (i.source_title)::text) AS title,
    COALESCE(NULLIF(l.description, ''::text), i.description) AS description,
    k.code AS item_kind,
    d.label AS denomination_label,
    c.label AS country,
    i.year_start,
    i.year_end,
    public.grade_display((stk.prefix)::text, (stk.suffix)::text, g.numeric_value, g.is_plus, (g.label)::text, ((gsc.code)::text = 'sheldon'::text)) AS grade,
    gs.code AS grading_service,
    bf.label AS bullion_form,
    mt.code AS metal,
    i.fineness,
    i.gross_weight_ozt,
    i.fine_weight_ozt
   FROM ((((((((((((public.listing l
     JOIN public.inventory_item i ON ((i.id = l.inventory_item_id)))
     JOIN public.item_kind k ON ((k.id = i.item_kind_id)))
     JOIN public.currency cur ON ((cur.id = l.currency_id)))
     JOIN public.sales_venue sv ON ((sv.id = l.sales_venue_id)))
     LEFT JOIN public.denomination d ON ((d.id = i.denomination_id)))
     LEFT JOIN public.country c ON ((c.id = i.country_id)))
     LEFT JOIN public.grade g ON ((g.id = i.grade_id)))
     LEFT JOIN public.grade_scale gsc ON ((gsc.id = g.grade_scale_id)))
     LEFT JOIN public.strike_type stk ON ((stk.id = i.strike_type_id)))
     LEFT JOIN public.grading_service gs ON ((gs.id = i.grading_service_id)))
     LEFT JOIN public.bullion_form bf ON ((bf.id = i.bullion_form_id)))
     LEFT JOIN public.metal mt ON ((mt.id = i.metal_id)))
  WHERE (l.is_active AND sv.is_own_store AND (l.format = 'fixed_price'::public.listing_format) AND (l.quantity_available > 0) AND (i.split_at IS NULL) AND (i.deleted_at IS NULL));

