CREATE UNIQUE INDEX uq_customer_venue_username ON public.customer USING btree (sales_venue_id, lower((venue_username)::text)) WHERE (venue_username IS NOT NULL);

CREATE UNIQUE INDEX uq_friedberg_number_identity ON public.friedberg_number USING btree (denomination_id, series_year, series_letter, note_type_id, district_letter, web_press, signature_combination_id, seal_color_id) NULLS NOT DISTINCT WHERE ((denomination_id IS NOT NULL) AND (series_year IS NOT NULL) AND (note_type_id IS NOT NULL));

CREATE UNIQUE INDEX uq_item_image_primary ON public.item_image USING btree (inventory_item_id) WHERE is_primary;

CREATE UNIQUE INDEX uq_offer_claim_active ON public.offer_claim USING btree (inventory_item_id) WHERE (state = 'active'::public.offer_claim_state);

CREATE UNIQUE INDEX uq_pcgs_type_identity ON public.pcgs_type USING btree (denomination_id, year, mint_id, variety) WHERE ((denomination_id IS NOT NULL) AND (year IS NOT NULL) AND (mint_id IS NOT NULL));

CREATE UNIQUE INDEX uq_purchase_order_vendor_number ON public.purchase_order USING btree (vendor_id, order_number) WHERE (order_number IS NOT NULL);

CREATE UNIQUE INDEX uq_sales_lot_item_open ON public.sales_lot_item USING btree (inventory_item_id) WHERE (released_at IS NULL);

CREATE UNIQUE INDEX uq_sales_venue_own_store ON public.sales_venue USING btree (is_own_store) WHERE is_own_store;

CREATE UNIQUE INDEX uq_storage_location_identity_no_identifier ON public.storage_location USING btree (storage_location_kind_id, institution) WHERE (identifier IS NULL);

